DROP PROCEDURE IF EXISTS add_migration;
DELIMITER ??
CREATE PROCEDURE `add_migration`()
BEGIN
DECLARE v INT DEFAULT 1;
SET v = (SELECT COUNT(*) FROM `migrations` WHERE `id`='20261026100004');
IF v = 0 THEN

ALTER TABLE `bonk_mastery` ADD COLUMN `excludes` INT UNSIGNED NOT NULL DEFAULT 0 COMMENT 'bonk_mastery.id that cannot be learned together with this node' AFTER `param`;


UPDATE `bonk_mastery` a JOIN `bonk_mastery` b ON b.`tree` = a.`tree` AND b.`row` = 3 AND b.`column` = 3 - a.`column`
SET a.`excludes` = b.`id`, a.`description` = CONCAT(a.`description`, ' Can''t be learned with ', b.`name`, '.')
WHERE a.`row` = 3 AND a.`column` IN (1, 2);

END IF;
END??
DELIMITER ;
CALL add_migration();
DROP PROCEDURE IF EXISTS add_migration;
